 INSERT INTO public.courses (course_id,title,code,description,duration,category,university,credits,status,is_demo) SELECT 'd52cac0d-00ee-54b4-bc4f-52b92e998578','IAM Operations Analyst L1 — Implement and Verify Employee Access','CYB-IAM-L1-007','Beginner-accessible, hands-on IAM operations for new cybersecurity graduates. One fictional Cedar Retail employee-access lifecycle across six 6E modules: see the workplace ticket and tool screens, repeat each demonstrated action exactly, run Python/Keycloak operations, check real allowed and denied report access, repair permissions, preserve approval-linked evidence, revoke approved access, and submit a separate unsolved joiner/leaver assessment for human review. The offline introductory simulator is distinct from the real Keycloak lab.','30 hours','Cybersecurity',NULL,NULL,'Active','true' WHERE true ON CONFLICT (course_id) DO UPDATE SET title=excluded.title,code=excluded.code,description=excluded.description,duration=excluded.duration,category=excluded.category,university=excluded.university,credits=excluded.credits WHERE courses.is_demo;
